{
  "hypothesis": "Short-term reversal following abnormally high-volume days in small-cap stocks predicts lower next-day returns.",
  "factors": [
    {
      "name": "vol_reversal_1",
      "expression": "RANK(TS_ZSCORE(TS_ARGMIN($volume, 30), 5))",
      "explanation": "measures the relative position of the lowest volume day in the past 30 days, z-scored over 5 days, to capture reversal after high-volume events"
    },
    {
      "name": "vol_reversal_2",
      "expression": "TS_PCTCHANGE(TS_CORR($volume, $return, 20), 1)",
      "explanation": "captures the change in correlation between volume and returns over 20 days, testing if high-volume days signal future reversal"
    },
    {
      "name": "vol_reversal_3",
      "expression": "RANK(DECAYLINEAR(TS_ARGMAX($volume, 60), 10))",
      "explanation": "uses decayed ranking of the highest volume day in 60 days to detect reversal potential in small-cap stocks"
    },
    {
      "name": "vol_reversal_4",
      "expression": "TS_MAD(TS_QUANTILE($return, 60, 0.9) - TS_QUANTILE($return, 60, 0.1), 10)",
      "explanation": "measures the dispersion of returns around high-volume days by comparing extreme quantiles and standardizing with MAD"
    },
    {
      "name": "vol_reversal_5",
      "expression": "RANK(SUMIF(TS_PCTCHANGE($volume, 5), $return, 10))",
      "explanation": "sums percentage changes in volume over 5 days and ranks their relationship to subsequent returns over 10 days"
    },
    {
      "name": "vol_reversal_6",
      "expression": "TS_ZSCORE(REGRESI($return, $volume, 20))",
      "explanation": "uses regression residuals of return on volume over 20 days to isolate reversal signals after high-volume periods"
    }
  ]
}

